/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const {
        listProps
    } = api.state; 
	const {
        list_filter,
  excl_list_filter
    } = event.payload.data.output;
 var fixed_filter = ''; 
   if (listProps.type && listProps.type == "excluded_records") {
        fixed_filter = excl_list_filter;
    } else  {
        fixed_filter = list_filter;
    }
    return {
		encodedQuery: fixed_filter
	};
}
